import { decryptMessage, encryptMessage, generateGroupKey, parseEnvelopes } from '../lib/chatCipher'
import type { ChatKey } from '../lib/types'
import { backend } from './index'
import type { MemberState, PoolState } from './queries'
import type { ChatRecipient } from './types'

/*
 * Private pool chat (DESIGN.md "Private chat"). It opens at the lock, for selected members who joined
 * with an encryption key. The pool creator is not part of it unless they are also a selected member:
 * the group key is generated by a member, never by the creator.
 */

const { platform, chat } = backend

/** Selected members who can take part: those who joined with an encryption key */
export function chatParticipants (state: PoolState): MemberState[] {
  return state.members.filter(m => m.join.encryptionKeyId != null)
}

/**
 * The key document that counts: the oldest one published by a participant, well-formed, with envelopes
 * only for participants. Later ones are ignored, so everyone uses the same group key.
 */
export function findChatKey (chatKeys: ChatKey[], state: PoolState): ChatKey | null {
  const participants = chatParticipants(state)
  const owners = new Set(participants.map(m => m.join.ownerId))
  const indexes = new Set(participants.map(m => m.shareIndex))
  return [...chatKeys]
    .sort((a, b) => a.createdAt - b.createdAt)
    .find(key => {
      if (key.lockId !== state.lock?.id || !owners.has(key.ownerId)) return false
      const slots = parseEnvelopes(key.envelopes)
      return slots != null && [...slots.keys()].every(i => indexes.has(i))
    }) ?? null
}

// Group keys stay in memory for the page's lifetime: never stored, never sent anywhere
const groupKeys = new Map<string, Uint8Array>()
const cacheKey = (lockId: string, identity: string): string => `${lockId}:${identity}`

/** Generates the group key, wraps it for every participant and publishes the key document */
export async function startPrivateChat (identity: string, state: PoolState): Promise<void> {
  if (state.lock == null) throw new Error('The pool is not locked')
  const participants = chatParticipants(state)
  if (!participants.some(m => m.join.ownerId === identity)) throw new Error('Only members with an encryption key can start the private chat')

  const recipients: ChatRecipient[] = []
  for (const member of participants) {
    const keys = await platform.getEncryptionKeys(member.join.ownerId)
    const key = keys.find(k => k.id === member.join.encryptionKeyId)
    // A key disabled since the join can't be encrypted to; that member is left out
    if (key != null) recipients.push({ shareIndex: member.shareIndex, publicKey: key.publicKey })
  }

  const groupKey = generateGroupKey()
  const envelopes = await chat.wrapGroupKey(groupKey, recipients)
  await platform.createChatKey(identity, { lockId: state.lock.id, envelopes })
}

/** Opens the member's envelope with their identity key. null when they have none in this key document. */
export async function loadGroupKey (identity: string, state: PoolState, chatKey: ChatKey): Promise<Uint8Array | null> {
  const cached = groupKeys.get(cacheKey(chatKey.lockId, identity))
  if (cached != null) return cached

  const me = chatParticipants(state).find(m => m.join.ownerId === identity)
  const envelope = me == null ? undefined : parseEnvelopes(chatKey.envelopes)?.get(me.shareIndex)
  if (me?.join.encryptionKeyId == null || envelope == null) return null

  const groupKey = await chat.unwrapGroupKey(identity, me.join.encryptionKeyId, envelope)
  if (groupKey != null) groupKeys.set(cacheKey(chatKey.lockId, identity), groupKey)
  return groupKey
}

export interface DecryptedMessage {
  id: string
  ownerId: string
  createdAt: number
  text: string
}

/** Messages from selected members that decrypt under the group key; anything else is dropped */
export async function loadPrivateMessages (state: PoolState, chatKey: ChatKey, groupKey: Uint8Array): Promise<DecryptedMessage[]> {
  const members = new Set(state.members.map(m => m.join.ownerId))
  const messages = await platform.listPrivateMessages(chatKey.lockId)
  const decrypted = await Promise.all(messages
    .filter(m => members.has(m.ownerId) && m.createdAt >= chatKey.createdAt)
    .map(async m => ({ id: m.id, ownerId: m.ownerId, createdAt: m.createdAt, text: await decryptMessage(groupKey, m.payload) })))
  return decrypted.filter((m): m is DecryptedMessage => m.text != null)
}

export async function sendPrivateMessage (identity: string, lockId: string, groupKey: Uint8Array, text: string): Promise<void> {
  await platform.sendPrivateMessage(identity, { lockId, payload: await encryptMessage(groupKey, text) })
}
